const assetModuleURL=import.meta.url;
import {PROPOSAL_SHA} from './pins.mjs';
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
/** Explicit optional proposal loader only; loading does not select/install the layer. */
export async function loadLampLayerProposal({fetcher=fetch,lightingManifest}){const root=new URL('./',assetModuleURL),read=async(name,pin)=>{const r=await fetcher(new URL(name,root));if(!r.ok)throw Error('LAMP_INPUT_MISSING');const b=await r.arrayBuffer();if(await sha(b)!==pin)throw Error('LAMP_INPUT_SHA_MISMATCH');return b},bytes=await read('LAYER_PROPOSAL.json',PROPOSAL_SHA),p=JSON.parse(new TextDecoder().decode(bytes));if(p.sourceLightingRevision!==lightingManifest?.revision||['OPEN','CLOSED'].some(k=>p.sourceSHAs[k]!==lightingManifest.sourceSHAs[k]))throw Error('LAMP_SOURCE_IDENTITY_DRIFT');const layers=[];for(const l of p.layers){const source=lightingManifest.fixtureRecords.find(x=>x.id===l.id);if(!source||source.kind!=='street_lamp'||source.groundY!==l.depthGroundY||JSON.stringify(source)!==JSON.stringify(l.sourceFixture))throw Error('LAMP_FIXTURE_IDENTITY_DRIFT');const mask=new Uint8Array(await read(l.maskFile,l.maskSHA)),[a,b,c,d]=l.box;if(mask.length!==(c-a)*(d-b)||!mask.every(x=>x===0||x===1))throw Error('LAMP_MASK_SHAPE');layers.push(Object.freeze({...l,mask}))}return Object.freeze({status:p.status,selected:false,layers:Object.freeze(layers)})}
import {ROOT_SELECTION_SHA} from './selection-pin.mjs';
export async function loadSelectedLampLayers({fetcher=fetch,lightingManifest}){const r=await fetcher(new URL('./ROOT_SELECTION.json',assetModuleURL));if(!r.ok)throw Error('ROOT_SELECTION_MISSING');const b=await r.arrayBuffer();if(await sha(b)!==ROOT_SELECTION_SHA)throw Error('ROOT_SELECTION_SHA_MISMATCH');const selection=JSON.parse(new TextDecoder().decode(b));if(selection.status!=='ROOT_SELECTED_TWO_RENDER_LAYERS_DEVELOPMENT_ONLY'||JSON.stringify(selection.selectedIds)!=='["L01","L07"]')throw Error('LAMP_SELECTION_SCOPE_DRIFT');const proposal=await loadLampLayerProposal({fetcher,lightingManifest});for(const l of proposal.layers){const selected=selection.layers.find(x=>x.id===l.id);if(!selected||selected.maskSHA!==l.maskSHA||selected.depthGroundY!==l.depthGroundY)throw Error('LAMP_SELECTION_PIN_DRIFT')}return Object.freeze({selection,layers:proposal.layers})}
